    // A graphNode represents a node in the object dependency graph.
    // Each node p in n.pred represents an edge p->n, and each node
    // s in n.succ represents an edge n->s; with a->b indicating that
    // a depends on b.
    
    template<typename T> requires gocpp::GoStruct<T>
    graphNode::operator T()
    {
        T result;
        result.obj = this->obj;
        result.pred = this->pred;
        result.succ = this->succ;
        result.index = this->index;
        result.ndeps = this->ndeps;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool graphNode::operator==(const T& ref) const
    {
        if (obj != ref.obj) return false;
        if (pred != ref.pred) return false;
        if (succ != ref.succ) return false;
        if (index != ref.index) return false;
        if (ndeps != ref.ndeps) return false;
        return true;
    }

    std::ostream& graphNode::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << obj;
        os << " " << pred;
        os << " " << succ;
        os << " " << index;
        os << " " << ndeps;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct graphNode& value)
    {
        return value.PrintTo(os);
    }

    // cost returns the cost of removing this node, which involves copying each
    // predecessor to each successor (and vice-versa).
    int rec::cost(graphNode* n)
    {
        return len(n->pred) * len(n->succ);
    }

    void rec::add(nodeSet* s, graphNode* p)
    {
        if(*s == nullptr)
        {
            *s = gocpp::make(gocpp::Tag<nodeSet>());
        }
        (*s)[p] = true;
    }

    // dependencyGraph computes the object dependency graph from the given objMap,
    // with any function nodes removed. The resulting graph contains only constants
    // and variables.
    gocpp::slice<graphNode*> dependencyGraph(gocpp::map<Object, declInfo*> objMap)
    {
        // M is the dependency (Object) -> graphNode mapping
        auto M = gocpp::make(gocpp::Tag<gocpp::map<dependency, graphNode*>>());
        for(auto [obj, gocpp_ignored] : objMap)
        {
            // only consider nodes that may be an initialization dependency
            {
                auto [obj_tmp, gocpp_id_2] = gocpp::getValue<dependency>(obj);
                if(auto& obj = obj_tmp; obj != nullptr)
                {
                    M[obj] = gocpp::InitPtr<graphNode>([=](auto& x) {
                        x.obj = obj;
                    });
                }
            }
        }

        // compute edges for graph M
        // (We need to include all nodes, even isolated ones, because they still need
        // to be scheduled for initialization in correct order relative to other nodes.)
        for(auto [obj, n] : M)
        {
            // for each dependency obj -> d (= deps[i]), create graph edges n->s and s->n
            for(auto [d, gocpp_ignored] : objMap[obj]->deps)
            {
                // only consider nodes that may be an initialization dependency
                {
                    auto [d_tmp, gocpp_id_3] = gocpp::getValue<dependency>(d);
                    if(auto& d = d_tmp; d != nullptr)
                    {
                        auto d_tmp = M[d];
                        auto& d = d_tmp;
                        rec::add(gocpp::recv(n->succ), d);
                        rec::add(gocpp::recv(d->pred), n);
                    }
                }
            }
        }

        // separate non-functions and functions
        gocpp::slice<graphNode*> G = {};
        gocpp::slice<graphNode*> funcG = {};
        for(auto [gocpp_ignored, n] : M)
        {
            if(auto [gocpp_id_4, ok] = gocpp::getValue<Func*>(n->obj); ok)
            {
                funcG = append(funcG, n);
            }
            else
            {
                G = append(G, n);
            }
        }

        // remove function nodes and collect remaining graph nodes in G
        // (Mutually recursive functions may introduce cycles among themselves
        // which are permitted. Yet such cycles may incorrectly inflate the dependency
        // count for variables which in turn may not get scheduled for initialization
        // in correct order.)
        // Note that because we recursively copy predecessors and successors
        // throughout the function graph, the cost of removing a function at
        // position X is proportional to cost * (len(funcG)-X). Therefore, we should
        // remove high-cost functions last.
        sort::Slice(funcG, [=](int i, int j) mutable -> bool
        {
            return rec::cost(gocpp::recv(funcG[i])) < rec::cost(gocpp::recv(funcG[j]));
        });
        for(auto [gocpp_ignored, n] : funcG)
        {
            // connect each predecessor p of n with each successor s
            // and drop the function node (don't collect it in G)
            for(auto [p, gocpp_ignored] : n->pred)
            {
                // ignore self-cycles
                if(p != n)
                {
                    // Each successor s of n becomes a successor of p, and
                    // each predecessor p of n becomes a predecessor of s.
                    for(auto [s, gocpp_ignored] : n->succ)
                    {
                        // ignore self-cycles
                        if(s != n)
                        {
                            rec::add(gocpp::recv(p->succ), s);
                            rec::add(gocpp::recv(s->pred), p);
                        }
                    }
                    // remove edge to n
                    remove(p->succ, n);
                }
            }
            for(auto [s, gocpp_ignored] : n->succ)
            {
                // remove edge to n
                remove(s->pred, n);
            }
        }

        // fill in index and ndeps fields
        for(auto [i, n] : G)
        {
            n->index = i;
            n->ndeps = len(n->succ);
        }

        return G;
    }

    // nodeQueue implements the container/heap interface;
    // a nodeQueue may be used as a priority queue.
    int rec::Len(nodeQueue a)
    {
        return len(a);
    }

    void rec::Swap(nodeQueue a, int i, int j)
    {
        auto [x, y] = std::tuple{a[i], a[j]};
        std::tie(a[i], a[j]) = std::tuple{y, x};
        std::tie(x->index, y->index) = std::tuple{j, i};
    }

    bool rec::Less(nodeQueue a, int i, int j)
    {
        auto [x, y] = std::tuple{a[i], a[j]};
        // nodes are prioritized by number of incoming dependencies (1st key)
        // and source order (2nd key)
        return x->ndeps < y->ndeps || x->ndeps == y->ndeps && rec::order(gocpp::recv(x->obj)) < rec::order(gocpp::recv(y->obj));
    }

    void rec::Push(nodeQueue* a, go_any x)
    {
        gocpp::panic("unreachable"_s);
    }

    go_any rec::Pop(nodeQueue* a)
    {
        auto n = len(*a);
        auto x = (*a)[n - 1];
        // for safety
        x->index = - 1;
        *a = (*a).make_slice(0, n - 1);
        return x;
    }

